export const ARTIFACT_ABIS: readonly ArtifactAbi[] = RAW.map((a) => ({
  name: a.name,
  source: a.source,
  sha256: a.sha256,
  abi: a.abi as Abi,
}))

const BY_NAME = new Map<string, ArtifactAbi>(ARTIFACT_ABIS.map((a) => [a.name, a]))

/** The ABI of a synced artifact. Throws rather than returning an empty ABI, which would decode as "unknown function" forever. */
export function artifactAbi(name: string): Abi {
  const found = BY_NAME.get(name)
  if (!found) throw new Error(`no synced artifact named ${name} — run pnpm abi:sync`)
  return found.abi
}

/** The sha256 of the artifact an ABI came from, for the drift test. */
export function artifactHash(name: string): string | null {
  return BY_NAME.get(name)?.sha256 ?? null
}
